		q[i]=(u[i]-C[i]*q[i+1])/B[i];
	}
	value=(v[1]*y[1]+v[n]*y[n])/(1+v[1]*q[1]+v[n]*q[n]);

	for(i=1;i<n+1;i++){
		x[i]=y[i]-q[i]*value;
	}
}

